-- Local synthetic fixture only. Never run on hosted data; no provider request is made.
begin;
create temporary table srf(owner_id uuid,wid uuid,sid uuid,request_id uuid,campaign_id uuid,run_id uuid,legacy_request_id uuid,legacy_campaign_id uuid,legacy_run_id uuid,profile_id uuid,test_id uuid,content_id uuid);
insert into srf values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null);
insert into auth.users(id) select owner_id from srf;
insert into public.bizoveya_workspaces(id,owner_id,name) select wid,owner_id,'Specialist runtime fixture' from srf;
insert into public.bizoveya_memberships(workspace_id,user_id,role) select wid,owner_id,'owner' from srf;
insert into public.bizoveya_sites(id,workspace_id,name,mode,kind,status,created_by) select sid,wid,'Specialist runtime site','native_business','business','active',owner_id from srf;
update srf set content_id=(select id from bizoveya_private.agent_definitions where kind='content' order by id limit 1);
create function pg_temp.srfexpect(q text,n text) returns void language plpgsql as $$begin begin execute q;exception when others then if strpos(sqlerrm,n)>0 then return;end if;raise;end;raise exception 'Expected %',n;end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,service_role',(select nspname from pg_namespace where oid=pg_my_temp_schema()));end;$$;grant all on srf to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from srf),true);
select public.bz_save_site_agent_preferences(wid,sid,'{"brandVoice":"practical","audience":"founders","guidance":"Private drafts only"}',0) from srf;
select public.bz_mutate_knowledge(wid,sid,gen_random_uuid(),'save','{"title":"Approved facts","filename":"facts.md","sourceText":"Bizoveya prepares private drafts.","facts":[{"id":"f1","text":"Bizoveya prepares private drafts."}]}',0) from srf;
select public.bz_mutate_knowledge(wid,sid,(select id from public.bizoveya_knowledge_sources where site_id=sid),'approve',null,1) from srf;
reset role;
update bizoveya_private.model_credentials set enabled=true where id='platform-gemini';
insert into bizoveya_private.model_profiles(id,slug,version,revision) select profile_id,'specialist-runtime-fixture',1,1 from srf;
insert into bizoveya_private.model_profile_versions(profile_id,version,document,reason) select profile_id,1,'{"name":"Fixture","provider":"gemini","credentialRef":"platform-gemini","modelId":"fixture-model","tier":"economical","maxOutputTokens":1500,"dailyBudgetCents":100}','Synthetic specialist runtime fixture' from srf;
insert into bizoveya_private.model_profile_checks(profile_id,version,credential_id,credential_version) select profile_id,1,'platform-gemini',1 from srf;
insert into bizoveya_private.model_test_runs(id,profile_id,profile_version,credential_id,credential_version,claim,status,result_code,input_tokens,output_tokens,reason,finished_at) select test_id,profile_id,1,'platform-gemini',1,gen_random_uuid(),'passed','response_matched',1,1,'Synthetic only',clock_timestamp() from srf;
insert into bizoveya_private.spending_policies(profile_id,version,profile_version,document,reason) select profile_id,1,1,jsonb_build_object('enabled',true,'inputRateMicros',0,'outputRateMicros',0,'requestFeeMicros',0,'dailyLimitMicros',10000,'runLimitMicros',10000,'validUntil',clock_timestamp()+interval '7 days','source','https://example.com/synthetic','reviewed',true),'Synthetic only' from srf;
update bizoveya_private.agent_versions set document=jsonb_set(document,'{modelTier}','"economical"') where version=1 and agent_id in(select id from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'));
update bizoveya_private.agent_definitions set preview_version=1 where kind in('coordinator','content','quality');
insert into bizoveya_private.agent_checks(agent_id,version) select id,1 from bizoveya_private.agent_definitions where kind in('coordinator','content','quality') on conflict do nothing;
insert into bizoveya_private.agent_model_bindings(agent_id,agent_version,profile_id,profile_version,credential_version,test_id,revision,enabled,reason) select a.id,1,s.profile_id,1,1,s.test_id,1,true,'Synthetic specialist runtime binding' from bizoveya_private.agent_definitions a cross join srf s where a.kind in('coordinator','content','quality');
create temporary table srteam as select jsonb_build_object('enabled',true,'agents',(select jsonb_agg(jsonb_build_object('kind',kind,'agentId',id,'agentVersion',1) order by kind) from bizoveya_private.agent_definitions where kind in('coordinator','content','quality'))) document;
create temporary table srspecialists as select jsonb_build_object('enabled',true,'assignments',jsonb_build_array(jsonb_build_object('channel','blog','agentId',content_id,'agentVersion',1),jsonb_build_object('channel','pinterest','agentId',content_id,'agentVersion',1),jsonb_build_object('channel','linkedin','agentId',content_id,'agentVersion',1))) document from srf;
grant all on srteam,srspecialists to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from srf),true);
select public.bz_save_site_agent_roster(wid,sid,jsonb_build_object('document',srteam.document,'expectedVersion',0,'reason','Enable reviewed shared runtime team.','reviewed',true)) from srf,srteam;
select public.bz_save_site_channel_specialists(wid,sid,jsonb_build_object('document',srspecialists.document,'expectedVersion',0,'reason','Enable reviewed channel specialists.','reviewed',true)) from srf,srspecialists;
select public.bz_agency_command(wid,sid,jsonb_build_object('action','request','id',request_id,'instruction','Prepare private Blog and LinkedIn drafts.','channels',jsonb_build_array('blog','linkedin'),'reviewed',true,'inputMode','text')) from srf;
select public.bz_delegate_agency_request_specialists(wid,sid,jsonb_build_object('id',request_id,'expectedVersion',1,'reason','Delegate this reviewed private request.','reviewed',true)) from srf;
select public.bz_handoff_agency_campaign(wid,sid,jsonb_build_object('id',request_id,'campaignId',campaign_id,'expectedVersion',2,'title','Specialist runtime campaign','reviewed',true)) from srf;
select public.bz_prepare_agency_generation(wid,sid,jsonb_build_object('id',request_id,'runId',run_id,'expectedVersion',3,'expectedCampaignVersion',1,'reviewed',true)) from srf;
select public.bz_prepare_agency_generation(wid,sid,jsonb_build_object('id',request_id,'runId',run_id,'expectedVersion',3,'expectedCampaignVersion',1,'reviewed',true)) from srf;
reset role;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select request_id from srf));if j#>>'{specialistRuntime,executionMode}'<>'shared-content-stage' or j#>>'{specialistRuntime,providerCallsPerContentStage}'<>'1' or jsonb_array_length(j#>'{specialistRuntime,channels}')<>2 or j#>>'{specialistRuntime,channels,0,state}'<>'prepared' or (select count(*) from bizoveya_private.agency_specialist_runtime_lineage)<>1 or (select count(*) from bizoveya_private.generation_runs)<>1 or exists(select 1 from bizoveya_private.generation_stage_runs) then raise exception 'Specialist runtime preparation or retry mismatch';end if;end;$$;
-- A compatible legacy/direct preparation remains valid; later reviewed delegation attaches lineage without another run.
select public.bz_agency_command(wid,sid,jsonb_build_object('action','request','id',legacy_request_id,'instruction','Prepare one private Pinterest draft.','channels',jsonb_build_array('pinterest'),'reviewed',true,'inputMode','text')) from srf;
select public.bz_handoff_agency_campaign(wid,sid,jsonb_build_object('id',legacy_request_id,'campaignId',legacy_campaign_id,'expectedVersion',1,'title','Legacy compatible runtime','reviewed',true)) from srf;
select public.bz_prepare_agency_generation(wid,sid,jsonb_build_object('id',legacy_request_id,'runId',legacy_run_id,'expectedVersion',2,'expectedCampaignVersion',1,'reviewed',true)) from srf;
select public.bz_delegate_agency_request_specialists(wid,sid,jsonb_build_object('id',legacy_request_id,'expectedVersion',3,'reason','Attach reviewed responsibility to this prepared request.','reviewed',true)) from srf;
do $$begin if (select count(*) from bizoveya_private.agency_specialist_runtime_lineage)<>2 or (bizoveya_private.agency_json((select legacy_request_id from srf))#>>'{specialistRuntime,runId}')<>(select legacy_run_id::text from srf) then raise exception 'Late reviewed delegation did not attach compatible lineage';end if;end;$$;
update bizoveya_private.agency_execution_tasks set state='recovery_required',last_reason='Synthetic recovery evidence.' where record_id=(select request_id from srf);
do $$begin if bizoveya_private.agency_json((select request_id from srf))#>>'{specialistRuntime,channels,0,state}'<>'recovery_required' then raise exception 'Recovery state not projected';end if;end;$$;
update bizoveya_private.generation_runs set status='succeeded',output_document='{"schema":"campaign-generation-output-v1","stages":{"content":{"blog":{"title":"Draft"},"linkedin":{"post":"Draft"}}}}',started_at=clock_timestamp(),finished_at=clock_timestamp() where id=(select run_id from srf);
update bizoveya_private.agency_execution_tasks set state='awaiting_human_review',last_reason='Synthetic output saved.' where record_id=(select request_id from srf);
insert into bizoveya_private.generation_reviews(generation_id,version,decision,reason,actor_id) select run_id,1,'accepted','Reviewed synthetic private drafts.',owner_id from srf;
do $$declare j jsonb;begin j:=bizoveya_private.agency_json((select request_id from srf));if j#>>'{specialistRuntime,channels,0,state}'<>'accepted' or j#>>'{specialistRuntime,channels,1,state}'<>'accepted' or j#>>'{specialistRuntime,channels,0,outputAvailable}'<>'true' then raise exception 'Accepted channel terminal state not projected';end if;end;$$;
select pg_temp.srfexpect('update bizoveya_private.agency_specialist_runtime_lineage set roster_version=2','bz_immutable_agency_handoff');
set local role authenticated;select set_config('request.jwt.claim.sub',(select owner_id::text from srf),true);select public.bz_agency_inventory(wid,sid) from srf;select pg_temp.srfexpect('select * from bizoveya_private.agency_specialist_runtime_lineage','permission denied');
reset role;delete from public.bizoveya_sites where id=(select sid from srf);
do $$begin if exists(select 1 from bizoveya_private.agency_specialist_runtime_lineage) then raise exception 'Specialist runtime site cascade failed';end if;end;$$;
rollback;
